'use strict';
window.addEventListener('DOMContentLoaded',()=>{let seen=false;try{seen=localStorage.getItem('observatory-online-welcome')==='yes'}catch{}if(seen)return;const d=document.createElement('dialog');d.innerHTML='<p class="eyebrow">WELCOME TO YOUR OBSERVATORY</p><h2>欢迎来到你的观星塔</h2><p>这是你自己的私人书房。你可以自由创建档案、角色、关系图，记录心情，收藏图片。</p><p><strong>内容仅保存在当前设备的当前浏览器中。</strong>其他访客看不到你的内容；同一设备、同一浏览器配置下则会共用这份档案。本站目前没有账号或跨设备云同步。</p><p class="hint">清除浏览器数据可能丢失记录，请定期导出完整备份。原本使用本机版的朋友，可以在这里导入之前导出的备份。</p><div class="dialogActions"><button class="primary">开始我的观星塔</button></div>';document.body.append(d);d.querySelector('button').onclick=()=>d.close();d.addEventListener('close',()=>{try{localStorage.setItem('observatory-online-welcome','yes')}catch{}d.remove()});d.showModal()});
